using DrawVerify.Core.Interfaces;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Data.Sqlite;
namespace DrawVerify.Infrastructure.Persistence;
public sealed class SqliteAuditRetentionRepository : IAuditRetentionRepository
{
    private readonly string _connectionString; private readonly ICentralizedLogger? _logger;
    public SqliteAuditRetentionRepository(string databasePath, ICentralizedLogger? logger = null) { _connectionString = new SqliteConnectionStringBuilder { DataSource = databasePath }.ToString(); _logger = logger; }
    public async Task<int> ApplyAsync(int retentionDays, CancellationToken cancellationToken = default) { if (retentionDays < 0) throw new ArgumentOutOfRangeException(nameof(retentionDays)); if (retentionDays == 0) return 0; try { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(cancellationToken); await using var transaction = (SqliteTransaction)await c.BeginTransactionAsync(cancellationToken); await using var q = c.CreateCommand(); q.Transaction = transaction; q.CommandText = "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='DocumentAuditLog'"; var hasDocumentAudit = Convert.ToInt32(await q.ExecuteScalarAsync(cancellationToken)) > 0; q.Parameters.Clear(); q.Parameters.AddWithValue("$cutoff", DateTimeOffset.UtcNow.AddDays(-retentionDays).ToString("O", CultureInfo.InvariantCulture)); int changed; if (hasDocumentAudit) { await ExecuteAsync(c, transaction, "DROP TRIGGER IF EXISTS TR_DocumentAuditLog_PreventDelete; DROP TRIGGER IF EXISTS TR_DocumentAuditLog_PreventUpdate;", cancellationToken); await using (var delete = c.CreateCommand()) { delete.Transaction = transaction; delete.CommandText = "DELETE FROM DocumentAuditLog WHERE TimestampUtc < $cutoff"; delete.Parameters.AddWithValue("$cutoff", q.Parameters["$cutoff"].Value); changed = await delete.ExecuteNonQueryAsync(cancellationToken); } await RebuildChainAsync(c, transaction, cancellationToken); await ExecuteAsync(c, transaction, "CREATE TRIGGER TR_DocumentAuditLog_PreventDelete BEFORE DELETE ON DocumentAuditLog BEGIN SELECT RAISE(ABORT, 'Document audit entries are append-only.'); END; CREATE TRIGGER TR_DocumentAuditLog_PreventUpdate BEFORE UPDATE ON DocumentAuditLog BEGIN SELECT RAISE(ABORT, 'Document audit entries are append-only.'); END;", cancellationToken); } else { q.CommandText = "DELETE FROM AuthenticationAuditLog WHERE TimestampUtc < $cutoff"; changed = await q.ExecuteNonQueryAsync(cancellationToken); } await transaction.CommitAsync(cancellationToken); return changed; } catch (Exception ex) { _logger?.Log(ex, "SQLite audit retention", $"Unable to apply {retentionDays}-day audit retention."); throw; } }
    private static async Task RebuildChainAsync(SqliteConnection c, SqliteTransaction transaction, CancellationToken token) { var rows = new List<(Guid Id, Guid DocumentId, int Action, string User, string Time, string Details, string Role, string Revision, string Version, string Metadata, string PreviousStatus, string NewStatus)>(); await using (var read = c.CreateCommand()) { read.Transaction = transaction; read.CommandText = "SELECT AuditId,DocumentId,Action,UserId,TimestampUtc,DetailsJson,ActorRole,DocumentRevision,DocumentVersion,EventMetadataJson,PreviousWorkflowStatus,NewWorkflowStatus FROM DocumentAuditLog ORDER BY DocumentId,TimestampUtc,AuditId"; await using var reader = await read.ExecuteReaderAsync(token); while (await reader.ReadAsync(token)) rows.Add((Guid.Parse(reader.GetString(0)), Guid.Parse(reader.GetString(1)), reader.GetInt32(2), reader.IsDBNull(3) ? string.Empty : reader.GetString(3), reader.GetString(4), reader.GetString(5), reader.IsDBNull(6) ? string.Empty : reader.GetString(6), reader.IsDBNull(7) ? string.Empty : reader.GetString(7), reader.IsDBNull(8) ? string.Empty : reader.GetString(8), reader.IsDBNull(9) ? "{}" : reader.GetString(9), reader.IsDBNull(10) ? string.Empty : reader.GetString(10), reader.IsDBNull(11) ? string.Empty : reader.GetString(11))); } Guid? document = null; Guid? predecessor = null; string? previousHash = null; foreach (var row in rows) { if (document != row.DocumentId) { document = row.DocumentId; predecessor = null; previousHash = null; } var hash = Hash(previousHash ?? string.Empty, row.Id, row.DocumentId, row.Action, row.User, DateTimeOffset.Parse(row.Time, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind), row.Revision, row.Metadata, row.Details, row.Role, row.Version, row.PreviousStatus, row.NewStatus); await using var update = c.CreateCommand(); update.Transaction = transaction; update.CommandText = "UPDATE DocumentAuditLog SET PredecessorAuditId=$predecessor,IntegrityHash=$hash WHERE AuditId=$id"; update.Parameters.AddWithValue("$predecessor", (object?)predecessor?.ToString() ?? DBNull.Value); update.Parameters.AddWithValue("$hash", hash); update.Parameters.AddWithValue("$id", row.Id.ToString()); await update.ExecuteNonQueryAsync(token); predecessor = row.Id; previousHash = hash; } }
    private static string Hash(string previous, Guid id, Guid document, int action, string actor, DateTimeOffset timestamp, string revision, string metadata, string details, string role, string version, string previousStatus, string newStatus) { var payload = $"{previous}|{id}|{document}|{action}|{actor}|{timestamp:O}|{revision}|{metadata}|{details}|{role}|{version}|{previousStatus}|{newStatus}"; return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(payload))); }
    private static async Task ExecuteAsync(SqliteConnection c, SqliteTransaction transaction, string sql, CancellationToken token) { await using var command = c.CreateCommand(); command.Transaction = transaction; command.CommandText = sql; await command.ExecuteNonQueryAsync(token); }
}
